"use client";

import { Menu, PanelLeftClose, PanelLeftOpen } from "lucide-react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState, type KeyboardEvent, type ReactNode } from "react";
import { cx } from "@/components/ui/_internal/cx";
import { focusableWithin } from "@/components/ui/_internal/position";
import { IconButton } from "@/components/ui/IconButton/IconButton";
import styles from "./SidebarShell.module.css";

export type SidebarNavItem = {
  href: string;
  label: string;
  icon?: ReactNode;
  /** Work waiting behind this item. */
  count?: number;
  /** Match the path exactly (for a section root like /admin). */
  exact?: boolean;
};

export type SidebarShellLayout = "sidebar" | "rail" | "header";

export type SidebarShellProps = {
  children: ReactNode;
  nav: ReadonlyArray<SidebarNavItem>;
  /** Pinned to the bottom of the sidebar (settings, sign out). Not shown in the header layout. */
  bottomNav?: ReadonlyArray<SidebarNavItem>;
  navLabel: string;
  /** Page title shown in the top bar (sidebar and rail layouts). */
  title?: ReactNode;
  /** Right side of the top bar: search, workspace switcher, profile. */
  topbarRight?: ReactNode;
  /** Full-width strip across the top of the frame, logo corner included (the admin context). */
  strip?: ReactNode;
  footer?: ReactNode;
  /**
   * sidebar (the default) = the expanded frosted sidebar and top bar, one
   * glass L. rail = the sidebar collapsed to an icon rail. header = no
   * sidebar: the logo, the nav as horizontal links and topbarRight in one
   * frosted top bar, with the page below.
   */
  layout?: SidebarShellLayout;
  /**
   * Shows a toggle in the top bar that collapses the sidebar to the rail and
   * back. The starting state is the layout prop (rail = collapsed) unless
   * defaultCollapsed says otherwise. Ignored in the header layout.
   */
  collapsible?: boolean;
  /** Start collapsed (as the rail). Defaults to layout === "rail". */
  defaultCollapsed?: boolean;
  /** Persists the collapsed state in localStorage under this key. Read after mount. */
  storageKey?: string;
  onCollapsedChange?: (collapsed: boolean) => void;
  /**
   * Below 900px (the frame's own width) the sidebar becomes an off-canvas
   * drawer opened from a menu button in the top bar. On by default; false
   * keeps the icon rail on narrow screens instead.
   */
  mobileDrawer?: boolean;
  /**
   * The frame width (px) below which the narrow layout (drawer, or rail with
   * mobileDrawer false) applies. Defaults to 900, or 600 when contained, so a
   * preview in a docs column keeps its desktop layout.
   */
  mobileBelow?: number;
  /** Treat the frame as narrow whatever its width: the docs use it to show the drawer at desktop width. */
  forceMobile?: boolean;
  /** Open the drawer on first render, without moving focus (a static docs preview). */
  defaultDrawerOpen?: boolean;
  /**
   * The logo corner's content: your logo as an element (an <img>, an inline
   * SVG, a wordmark). Defaults to a sample glyph and "Acme", the placeholder brand.
   */
  logo?: ReactNode;
  /** The logo for the rail's narrow corner: a mark without the wordmark. Defaults to the glyph. */
  logoCompact?: ReactNode;
  /**
   * The logo corner's ground. glass (the default) = the same frosted glass as
   * the sidebar and top bar, one continuous L. fill = a set colour behind the
   * logo, from --logo-corner-bg (ink --logo-corner-ink), for brands whose
   * guidelines require one.
   */
  logoCorner?: "glass" | "fill";
  /** A logo image URL (or data URL) for the corner, in place of `logo`. Up to 176px wide. */
  logoSrc?: string;
  /** Alt text for logoSrc. Required in practice whenever logoSrc is set. */
  logoAlt?: string;
  /** Overrides the pathname match; used by the docs previews. */
  activeHref?: string;
  /**
   * Fill the parent instead of the viewport. The docs render the shell inside
   * a fixed-height frame so the sticky chrome can be seen working.
   */
  contained?: boolean;
};


/**
 * The dashboard frame: a full-height glass sidebar and a glass top bar
 * forming one frosted L over the page gradient, collapsible to an icon rail,
 * or a header-only top-nav layout. Only <main> scrolls, so the chrome never
 * moves and its blur always has content passing beneath it. Narrow frames get
 * an off-canvas drawer. Presentation only: no auth here (gate inside each
 * page.tsx).
 */
export function SidebarShell({
  children,
  nav,
  bottomNav,
  navLabel,
  title,
  topbarRight,
  strip,
  footer,
  layout = "sidebar",
  collapsible,
  defaultCollapsed,
  storageKey,
  onCollapsedChange,
  mobileDrawer = true,
  mobileBelow,
  forceMobile,
  defaultDrawerOpen,
  logo,
  logoCompact,
  logoCorner = "glass",
  logoSrc,
  logoAlt,
  activeHref,
  contained,
}: SidebarShellProps) {
  const pathname = usePathname();
  const current = activeHref ?? pathname;
  const drawerId = useId();

  // ── Collapsed state: from the layout prop, kept in step when it changes
  // (the Rime Studio switches it live), and optionally persisted.
  const [collapsed, setCollapsedState] = useState(defaultCollapsed ?? layout === "rail");
  const [prevLayout, setPrevLayout] = useState(layout);
  if (layout !== prevLayout) {
    setPrevLayout(layout);
    setCollapsedState(layout === "rail");
  }

  useEffect(() => {
    if (!storageKey) return;
    try {
      const saved = window.localStorage.getItem(storageKey);
      if (saved === "1" || saved === "0") {
        const frame = requestAnimationFrame(() => setCollapsedState(saved === "1"));
        return () => cancelAnimationFrame(frame);
      }
    } catch {
      // Storage blocked: the default state stands.
    }
  }, [storageKey]);

  const setCollapsed = (next: boolean) => {
    setCollapsedState(next);
    onCollapsedChange?.(next);
    if (storageKey) {
      try {
        window.localStorage.setItem(storageKey, next ? "1" : "0");
      } catch {
        // Storage blocked or full: the state lasts for this page only.
      }
    }
  };

  // ── Narrow frames: measured on the frame itself, so a contained preview
  // behaves like the viewport it stands in for.
  const frameRef = useRef<HTMLDivElement>(null);
  const [narrow, setNarrow] = useState(false);
  const below = mobileBelow ?? (contained ? 600 : 900);
  useLayoutEffect(() => {
    const el = frameRef.current;
    if (!el) return;
    const check = () => setNarrow(el.clientWidth > 0 && el.clientWidth < below);
    check();
    const ro = new ResizeObserver(check);
    ro.observe(el);
    return () => ro.disconnect();
  }, [below]);
  const mobile = Boolean(forceMobile) || narrow;

  const header = layout === "header";
  const drawer = !header && mobile && mobileDrawer;
  const rail = !header && !drawer && (collapsed || mobile);

  // ── Drawer: open state, focus in on open, back to the button on close.
  const [drawerOpen, setDrawerOpen] = useState(Boolean(defaultDrawerOpen));
  const sidebarRef = useRef<HTMLElement>(null);
  const menuButtonRef = useRef<HTMLButtonElement>(null);
  const userOpened = useRef(false);
  const open = drawer && drawerOpen;

  useEffect(() => {
    if (!open || !userOpened.current) return;
    const el = sidebarRef.current;
    (el ? focusableWithin(el)[0] : undefined)?.focus();
  }, [open]);

  const closeDrawer = useCallback(() => {
    setDrawerOpen(false);
    if (userOpened.current) menuButtonRef.current?.focus();
    userOpened.current = false;
  }, []);

  const onSidebarKey = (e: KeyboardEvent<HTMLElement>) => {
    if (!open) return;
    if (e.key === "Escape") {
      e.preventDefault();
      closeDrawer();
      return;
    }
    if (e.key !== "Tab" || !sidebarRef.current) return;
    const items = focusableWithin(sidebarRef.current);
    if (!items.length) return;
    const first = items[0];
    const last = items[items.length - 1];
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  };

  const isActive = (item: SidebarNavItem) =>
    item.exact ? current === item.href : current === item.href || current.startsWith(`${item.href}/`);

  const renderItem = (item: SidebarNavItem) => {
    const active = isActive(item);
    return (
      <li key={item.href}>
        <Link
          href={item.href}
          aria-current={active ? "page" : undefined}
          className={cx(styles.item, active && styles.active)}
          title={item.label}
          onClick={open ? closeDrawer : undefined}
        >
          {item.icon ? <span className={styles.icon}>{item.icon}</span> : null}
          <span className={styles.label}>{item.label}</span>
          {item.count ? (
            <span className={styles.badge} aria-label={`${item.count} waiting`}>
              {item.count}
            </span>
          ) : null}
        </Link>
      </li>
    );
  };

  const glyph = (
    <span className={styles.glyph} aria-hidden="true">
      A
    </span>
  );
  const fullLogo = logoSrc ? (
    // eslint-disable-next-line @next/next/no-img-element -- any URL or data URL; next/image adds nothing here
    <img src={logoSrc} alt={logoAlt ?? ""} width={176} height={53} className={styles.logo} />
  ) : (
    (logo ?? (
      <span className={styles.wordmark}>
        {glyph}
        Acme
      </span>
    ))
  );
  const compactLogo = logoCompact ?? (
    <span className={styles.wordmark}>
      {glyph}
      <span className="sr-only">Acme</span>
    </span>
  );

  const toggle =
    collapsible && !header && !mobile ? (
      <IconButton
        label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
        icon={collapsed ? <PanelLeftOpen size={17} /> : <PanelLeftClose size={17} />}
        variant="ghost"
        aria-expanded={!collapsed}
        onClick={() => setCollapsed(!collapsed)}
        className={styles.toggle}
      />
    ) : null;

  const menuButton = drawer ? (
    <IconButton
      ref={menuButtonRef}
      label={open ? "Close navigation" : "Open navigation"}
      icon={<Menu size={18} />}
      variant="ghost"
      aria-expanded={open}
      aria-controls={drawerId}
      onClick={() => {
        if (open) closeDrawer();
        else {
          userOpened.current = true;
          setDrawerOpen(true);
        }
      }}
      className={styles.toggle}
    />
  ) : null;

  const mainArea = contained ? (
    <div className={styles.main}>
      <div className={styles.content}>{children}</div>
      {footer}
    </div>
  ) : (
    <main id="main" className={styles.main}>
      <div className={styles.content}>{children}</div>
      {footer}
    </main>
  );

  return (
    <div
      ref={frameRef}
      className={cx(
        styles.frame,
        contained && styles.contained,
        header && styles.headerLayout,
        rail && styles.rail,
        drawer && styles.drawerMode,
        open && styles.drawerOpen,
      )}
      data-layout={header ? "header" : rail ? "rail" : drawer ? "drawer" : "sidebar"}
    >
      {contained ? null : (
        <a href="#main" className={styles.skip}>
          Skip to content
        </a>
      )}
      {/* Spans the full width, across the logo corner too, so an admin session
          is marked edge to edge. */}
      {strip ? <div className={styles.strip}>{strip}</div> : null}

      {header ? (
        <div className={styles.headerColumn}>
          <header className={cx(styles.topbar, styles.topnav)}>
            <div className={cx(styles.headerBrand, logoCorner === "fill" && styles.brandFill)}>{fullLogo}</div>
            <nav aria-label={navLabel} className={styles.topnavNav}>
              <ul className={styles.topnavList}>{nav.map(renderItem)}</ul>
            </nav>
            {topbarRight ? <div className={styles.right}>{topbarRight}</div> : null}
          </header>
          {mainArea}
        </div>
      ) : (
        <div className={styles.body}>
          <aside
            ref={sidebarRef}
            id={drawerId}
            className={styles.sidebar}
            onKeyDown={onSidebarKey}
            aria-label={drawer ? `${navLabel} menu` : undefined}
            // Off-canvas and closed: out of the tab order and the accessibility tree.
            inert={drawer && !open ? true : undefined}
          >
            <div className={cx(styles.brand, logoCorner === "fill" && styles.brandFill)}>{rail ? compactLogo : fullLogo}</div>
            <nav aria-label={navLabel} className={styles.nav}>
              <ul className={styles.list}>{nav.map(renderItem)}</ul>
              {bottomNav?.length ? <ul className={cx(styles.list, styles.bottom)}>{bottomNav.map(renderItem)}</ul> : null}
            </nav>
          </aside>
          {drawer ? <div className={styles.scrim} aria-hidden="true" onClick={closeDrawer} /> : null}

          <div className={styles.column} inert={open ? true : undefined}>
            <header className={styles.topbar}>
              <div className={styles.left}>
                {menuButton ?? toggle}
                {/* Not a heading: each page owns its h1. This names the area. */}
                {title ? <p className={styles.title}>{title}</p> : null}
              </div>
              {topbarRight ? <div className={styles.right}>{topbarRight}</div> : null}
            </header>
            {mainArea}
          </div>
        </div>
      )}
    </div>
  );
}

/* The dashboard frame: a frosted sidebar and top bar over the page field.

   Chrome hooks: every chrome colour reads a custom property. The corner and
   strip are tokens in tokens.css (--logo-corner-bg, --admin-strip-bg); the
   rest fall back to the default theme, so setting none changes nothing.
   Set any of them on a wrapper to try options:
   --logo-corner-bg, --admin-strip-bg, --sidebar-bg, --topbar-bg,
   --page-background, and for dark sidebars --sidebar-ink, --sidebar-ink-hover,
   --sidebar-hover-bg, --sidebar-active-bg, --sidebar-active-ink,
   --sidebar-active-shadow, --sidebar-active-badge-bg, --sidebar-rule.

   The gradient is painted once on the whole frame; sidebar and top bar are
   white frosted glass over it, so the chrome shares the field's colour and
   the whole screen reads as one surface. */

.frame {
  --sidebar-width: var(--shell-sidebar-width, 212px);
  --strip-height: 28px;
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100dvh;
  overflow: hidden;
  background: var(--page-background);
}

/* Sidebar and column side by side under the (optional) full-width strip. */
.body {
  position: relative;
  display: flex;
  flex: 1;
  min-height: 0;
}

/* Docs preview: fill a fixed-height parent instead of the viewport. */
.contained {
  height: 100%;
  border-radius: inherit;
}

/* ── Sidebar ──────────────────────────────────────────────────────────── */

.sidebar {
  position: relative;
  z-index: 2;
  transition: width var(--dur-slow) var(--ease), transform var(--dur-slow) var(--ease-out);
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  width: var(--sidebar-width);
  height: 100%;
  padding: 20px 12px;
  background: var(--sidebar-bg, var(--chrome-sidebar));
  -webkit-backdrop-filter: var(--chrome-backdrop, var(--blur-chrome) saturate(160%));
  backdrop-filter: var(--chrome-backdrop, var(--blur-chrome) saturate(160%));
  /* No border: the tinted side shadow is the edge. */
}

/* Shadows are cast by the full chrome shapes (a 1px strip blurs to nothing).
   The sidebar's edge shadow starts below the top bar, so it falls on the
   content only and never darkens the header. */
.sidebar::after {
  content: "";
  position: absolute;
  top: var(--topbar-height);
  left: 0;
  right: 0;
  bottom: 0;
  box-shadow: var(--sidebar-shadow, 8px 0 28px rgba(var(--rgb-brand-deep), 0.12), 1px 0 3px rgba(var(--rgb-contact), 0.06));
  /* Clip the blur's upward bleed so none of it reaches the header. */
  clip-path: inset(0 -60px 0 0);
  pointer-events: none;
}

/* The logo corner: flush, square, edge to edge and exactly the top bar's
   height, so it meets the header as one corner piece. By default it is the
   same frosted glass as the sidebar and top bar (one continuous L), with the
   same hairline under it as the top bar. logoCorner="fill" opts in to a set
   colour behind the logo (--logo-corner-bg, ink --logo-corner-ink), for
   brands whose guidelines require one. With a context strip the strip runs
   straight across its top edge: a deliberate cap, not a seam. */
.brand {
  display: flex;
  align-items: center;
  justify-content: center;
  height: var(--brand-height, var(--topbar-height));
  margin: -20px -12px 20px;
  padding: 0 18px;
  background: transparent;
  border-bottom: 1px solid rgba(var(--rgb-white), 0.4);
  color: var(--ink-heading);
}

.brandFill {
  background: var(--logo-corner-bg);
  border-bottom-color: transparent;
  color: var(--logo-corner-ink, var(--ink-inverse));
}

/* An image logo: up to 176px wide, never taller than the bar allows. */
.logo {
  display: block;
  width: var(--shell-logo-width, 176px);
  max-width: 100%;
  height: auto;
  max-height: calc(var(--topbar-height) - 16px);
  object-fit: contain;
  /* Rime Studio hook: a theme can swap the artwork from CSS alone
     (--shell-logo: url(...)). Unset, the <img> renders its own src. */
  content: var(--shell-logo, normal);
}

/* The default mark when no logo is given: a square glyph and a wordmark in
   inverse ink on the corner. */
.wordmark {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 700;
  letter-spacing: var(--tracking-display);
  color: inherit;
  white-space: nowrap;
}

.glyph {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: var(--r-sm);
  background: var(--brand-gradient);
  box-shadow: var(--glow-sm);
  font-size: 14px;
  color: var(--ink-inverse);
}

.brandFill .glyph {
  background: rgba(255, 255, 255, 0.2);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.35);
  color: inherit;
}

.nav {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
}

.list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.bottom {
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid var(--sidebar-rule, rgba(var(--rgb-brand-deep), 0.08));
}

.item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: calc(10px * var(--density)) calc(12px * var(--density));
  border-radius: var(--sidebar-item-radius, var(--r-lg));
  font-size: var(--text-small);
  font-weight: 700;
  color: var(--sidebar-ink, var(--ink-muted));
  text-decoration: none;
  transition:
    background var(--dur) var(--ease),
    color var(--dur) var(--ease),
    box-shadow var(--dur) var(--ease);
}

.item:hover {
  background: var(--sidebar-hover-bg, rgba(var(--rgb-white), 0.65));
  color: var(--sidebar-ink-hover, var(--ink-heading));
}

.item:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

/* The primary-nav gesture: the solid gradient pill with brand glow.
   In the sidebar frame this is the one gradient on the chrome; page actions
   still carry their own. */
.active,
.active:hover {
  background: var(--sidebar-active-bg, var(--brand-gradient));
  color: var(--sidebar-active-ink, var(--ink-inverse));
  box-shadow: var(--sidebar-active-shadow, var(--glow-md), inset 0 1px 0 rgba(var(--rgb-white), 0.18));
}

.icon {
  display: inline-flex;
  flex-shrink: 0;
  width: 16px;
  height: 16px;
}

.icon :global(svg) {
  width: 16px;
  height: 16px;
}

.label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: var(--r-full);
  background: var(--danger-base-solid);
  color: var(--ink-inverse);
  font-size: 10px;
  font-weight: 700;
}

.active .badge {
  background: var(--sidebar-active-badge-bg, rgba(var(--rgb-white), 0.25));
}

/* ── Column: strip, top bar, scrolling main ───────────────────────────── */

.column {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  overflow: hidden;
}

/* The context strip (an admin session, a staging site), night to deep, across the
   top of the frame, logo corner included. The text starts on the top bar's
   left edge, so it lines up with the page rather than the logo. */
.strip {
  position: relative;
  z-index: 3;
  display: flex;
  align-items: center;
  flex-shrink: 0;
  height: var(--strip-height);
  padding: 0 24px 0 calc(var(--sidebar-width) + 24px);
  background: var(--admin-strip-bg);
  color: var(--ink-inverse);
  font-size: var(--text-micro);
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.topbar {
  position: relative;
  z-index: 1;
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: var(--topbar-height);
  padding: 10px 24px;
  background: var(--topbar-bg, var(--chrome-topbar));
  -webkit-backdrop-filter: var(--chrome-backdrop, var(--blur-chrome) saturate(160%));
  backdrop-filter: var(--chrome-backdrop, var(--blur-chrome) saturate(160%));
  /* Near-invisible edge: the bar melts into the content. */
  border-bottom: 1px solid rgba(var(--rgb-white), 0.4);
}

/* The header casts the same soft shadow as the sidebar, downward onto
   the content. Clipped on the left, right and top so none of it lands on the
   sidebar or bleeds upward. */
.topbar::after {
  content: "";
  position: absolute;
  inset: 0;
  box-shadow: var(--topbar-shadow, var(--chrome-shadow));
  clip-path: inset(0 0 -60px 0);
  pointer-events: none;
}

.title {
  margin: 0;
  font-family: var(--font-display);
  font-size: var(--shell-title-size, 26px);
  font-weight: 400;
  line-height: 1;
  letter-spacing: -0.01em;
  color: var(--ink-heading);
}

.right {
  display: flex;
  align-items: center;
  gap: 10px;
}

.main {
  display: flex;
  flex: 1;
  flex-direction: column;
  overflow-y: auto;
  padding: 20px 24px 8px;
}

.content {
  flex: 1;
}

.skip {
  position: absolute;
  top: 8px;
  left: 8px;
  z-index: 10;
  padding: 8px 14px;
  border-radius: var(--r-sm);
  background: var(--surface-solid);
  box-shadow: var(--shadow-float);
  font-weight: 700;
  color: var(--ink-brand);
  transform: translateY(-160%);
  transition: transform var(--dur) var(--ease);
}

.skip:focus {
  transform: none;
  outline: none;
  box-shadow: var(--shadow-float), var(--focus-ring);
}

/* ── Artwork hooks ─────────────────────────────────────────────────────
   Optional artwork, off by default: set --sidebar-art, --logo-corner-art or
   --page-art (a url()) with its -opacity partner. Painted by
   pseudo-elements, so they are never in the accessibility tree and never
   take a click; static, no motion. Each sits under its surface's content. */

.brand {
  position: relative;
  z-index: 1;
  overflow: hidden;
  isolation: isolate;
}

.brand::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: var(--logo-corner-art, none) no-repeat right -46px bottom -70px / auto 170px;
  opacity: var(--logo-corner-art-opacity, 0);
  pointer-events: none;
}

.nav {
  position: relative;
  z-index: 1;
}

.sidebar::before {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--sidebar-art, none) no-repeat center bottom -96px / 236px auto;
  opacity: var(--sidebar-art-opacity, 0);
  pointer-events: none;
}

/* The icon rail is too narrow to carry it (see .rail below). */

.frame::before {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--page-art, none) no-repeat right -150px bottom -210px / 560px auto;
  opacity: var(--page-art-opacity, 0);
  pointer-events: none;
}

/* Above the page artwork; the strip already stacks at 3. */
.body {
  z-index: 1;
}

/* ── Top bar, left cluster: the collapse toggle or menu button, then the title ── */
.left {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.toggle {
  flex-shrink: 0;
  margin-left: -8px;
}

/* ── Rail: the sidebar collapsed to icons ─────────────────────────────────
   Labels hide (each item keeps its title for a tooltip), the logo corner
   shows the compact mark, and counts sit on the icon. */
.rail {
  --sidebar-width: var(--shell-rail-width, 68px);
}

.rail .sidebar {
  padding: 20px 10px;
}

.rail .brand {
  margin: -20px -10px 20px;
  padding: 0;
}

.rail .label {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

.rail .item {
  position: relative;
  justify-content: center;
  padding: 12px;
}

.rail .badge {
  position: absolute;
  top: 3px;
  right: 3px;
}

.rail .sidebar::before {
  display: none;
}

/* ── Drawer: the sidebar off canvas on narrow frames ──────────────────────
   Positioned inside the frame (not the viewport), so a contained preview
   works the same as the page. A scrim covers the column while it is open. */
.drawerMode .sidebar {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  z-index: 4;
  width: var(--shell-drawer-width, 264px);
  max-width: 85%;
  transform: translateX(-105%);
  visibility: hidden;
  background: var(--sidebar-drawer-bg, var(--modal-surface));
  -webkit-backdrop-filter: var(--modal-blur);
  backdrop-filter: var(--modal-blur);
  box-shadow: var(--shadow-modal);
  transition:
    transform var(--dur-slow) var(--ease-out),
    visibility 0s linear var(--dur-slow);
}

.drawerMode .sidebar::after {
  display: none;
}

.drawerOpen .sidebar {
  transform: none;
  visibility: visible;
  transition: transform var(--dur-slow) var(--ease-out);
}

.scrim {
  position: absolute;
  inset: 0;
  z-index: 3;
  background: var(--scrim);
  -webkit-backdrop-filter: var(--blur-scrim);
  backdrop-filter: var(--blur-scrim);
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--dur-slow) var(--ease);
}

.drawerOpen .scrim {
  opacity: 1;
  pointer-events: auto;
}

.drawerMode .topbar,
.drawerMode .main {
  padding-left: 16px;
  padding-right: 16px;
}

.drawerMode .strip {
  padding-left: 16px;
}

/* ── Header only: no sidebar, one frosted top bar with the nav in it ───── */
.headerColumn {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
}

.topnav {
  justify-content: flex-start;
  gap: 24px;
  box-shadow: var(--topbar-shadow, var(--chrome-shadow));
}

.topnav::after {
  display: none;
}

.headerBrand {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  color: var(--ink-heading);
}

.headerBrand.brandFill {
  height: calc(var(--topbar-height) - 16px);
  padding: 0 14px;
  border-radius: var(--r-md);
}

.headerBrand .logo {
  max-height: calc(var(--topbar-height) - 24px);
}

.topnavNav {
  flex: 1;
  min-width: 0;
  overflow-x: auto;
  scrollbar-width: none;
}

.topnavNav::-webkit-scrollbar {
  display: none;
}

.topnavList {
  display: flex;
  align-items: center;
  gap: 4px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.topnav .item {
  padding: 8px 12px;
  white-space: nowrap;
}

.topnav .icon {
  display: none;
}

.headerLayout .strip {
  padding-left: 24px;
}

.headerLayout .main {
  padding-top: 24px;
}

@media (max-width: 640px) {
  .topnav {
    gap: 12px;
    padding: 10px 16px;
  }

  .headerLayout .main {
    padding: 16px 16px 8px;
  }
}
